/* ---------- knowledge ---------- */
const ocrModel=()=>S.cfg.ocr_model||(S.models.find(m=>m.caps.includes('vision')&&/ocr/.test(m.name))||S.models.find(m=>m.caps.includes('vision'))||{}).name||'';
const stc={ready:'#22c55e',partial:'#f59e0b',failed:'#ef4444',queued:'#9b9b9b',processing:'#3b82f6',ocr:'#3b82f6'},busy=s=>['queued','processing','ocr'].includes(s);
const badge=s=>`<span style="color:${stc[s]||'#999'}">● ${s}</span>`;
const modal=h=>{$('#modal').innerHTML=`<div>${h}</div>`;$('#modal').style.display='flex'},closeModal=()=>$('#modal').style.display='none';
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#amenu').style.display='none';$('#menu').style.display='none'}});
$('#kfile').onchange=async e=>{const fs=[...e.target.files];e.target.value='';if(!fs.length)return;const fd=new FormData();fd.append('coll',S.upColl);fd.append('ocr_model',ocrModel());fs.forEach(f=>fd.append('files',f));
 const r=await fetch('/api/kb/sources',{method:'POST',body:fd}),d=await r.json();if(!r.ok)return alert(d.detail||r.status);const er=d.filter(x=>x.error).map(x=>x.name+': '+x.error);if(er.length)alert(er.join('\n'));collView(S.upColl)};
async function kbView(){const cs=await api('/api/kb/collections'),tot=cs.reduce((a,c)=>a+c.n,0),bad=cs.reduce((a,c)=>a+c.bad,0);S.kbc=null;
 $('#main').innerHTML=`<div class="pg"><div style="display:flex;gap:10px;align-items:center"><div><h1>Knowledge</h1><div class="mu">${cs.length} collections · ${tot} documents${bad?` · <span style="color:#fca5a5">${bad} need attention</span>`:''} · keyword search (embeddings not set up)</div></div><button class="btn" style="margin-left:auto" data-a="newcoll">Create collection</button></div>
 <div style="display:flex;gap:8px;margin:14px 0"><input type="search" id="kq" class="in" style="flex:1" placeholder="Search all documents"><button class="btn" id="kqb">Search</button></div><div id="kres"></div>
 <div class="grid">${cs.map(c=>`<div class="card"><b>${esc(c.name)}</b><div class="mu">${c.n} docs · ${c.ready} ready${c.bad?` · ${c.bad} issues`:''}</div><div style="display:flex;gap:6px;margin-top:10px"><button class="btn" data-a="kopen:${c.id}">Open</button><button class="btn" data-a="kask:c:${c.id}">Ask</button></div></div>`).join('')||'<div class="mu">No collections yet — create one, then add documents.</div>'}</div></div>`;
 const go1=async()=>{const q=$('#kq').value.trim();if(!q)return;const r=await api('/api/kb/search?q='+encodeURIComponent(q));$('#kres').innerHTML=r.length?r.map(h=>`<div class="card" style="margin-bottom:8px;cursor:pointer" data-a="vsrc:${h.sid}:${h.loc}"><b>${esc(h.title)}</b> <span class="mu">${h.label} ${h.loc}</span><div class="mu">${esc(h.text)}</div></div>`).join(''):'<div class="mu">No matches.</div>'};
 $('#kqb').onclick=go1;$('#kq').onkeydown=e=>{if(e.key==='Enter')go1()}}
async function collView(id){const[cs,ss]=await Promise.all([api('/api/kb/collections'),api('/api/kb/sources?coll='+id)]),c=cs.find(x=>x.id===id);if(!c)return go('kb');S.kbc=id;const sc=$('.pg')?.scrollTop||0;
 $('#main').innerHTML=`<div class="pg"><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><button class="btn" data-a="nav:kb">← Knowledge</button><h1 style="margin:0">${esc(c.name)}</h1><span style="margin-left:auto;display:flex;gap:6px;flex-wrap:wrap"><button class="btn on" data-a="kup:${id}">Add documents</button><button class="btn" data-a="kask:c:${id}">Ask questions</button><button class="btn" data-a="krn:${id}">Rename</button><button class="btn" data-a="kexp:${id}">Export metadata</button><button class="btn" data-a="kdel:${id}">Delete</button></span></div>
 <div class="card" style="margin-top:14px"><table><tr><th>Document</th><th>Type</th><th>Size</th><th>Status</th><th>Progress</th><th></th></tr>${ss.map(s=>`<tr><td>${esc(s.title)}${s.error?`<div style="color:#fca5a5;font-size:12px">${esc(s.error)}</div>`:''}</td><td>${esc(s.extension||s.type)}</td><td>${Number(s.size_bytes||0).toLocaleString()} B</td><td>${badge(s.status)}</td><td>${s.done}/${s.pages}${s.failed?` · <span style="color:#fca5a5">${s.failed} failed</span>`:''}</td><td style="white-space:nowrap"><button class="btn" data-a="vsrc:${s.id}:0">View</button> <button class="btn" data-a="kask:s:${s.id}">Ask</button> <button class="btn" data-a="kre:${s.id}">Re-index</button> <button class="btn" data-a="ksdel:${s.id}">Remove</button></td></tr>`).join('')||'<tr><td colspan="6" class="mu">No documents yet.</td></tr>'}</table></div></div>`;
 $('.pg').scrollTop=sc;clearInterval(pt);if(ss.some(s=>busy(s.status)))pt=setInterval(()=>S.page==='kb'&&S.kbc===id&&collView(id),2500)}
async function viewSrc(sid,loc){const s=await api('/api/kb/sources/'+sid);loc=+loc||(s.pages.find(p=>p.status==='ok')||s.pages[0]||{}).loc;const L={pdf:'Page',notebook:'Cell',image:'Image',text:'Section'}[s.type]||'Section';
 const pg=loc?await api(`/api/kb/sources/${sid}/pages/${loc}`):{text:'',status:'—'};S.pgtext=pg.text;
 modal(`<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><b>${esc(s.title)}</b>${badge(s.status)}<span style="margin-left:auto;display:flex;gap:6px"><a class="btn" href="/api/kb/sources/${sid}/export?fmt=txt">TXT</a><a class="btn" href="/api/kb/sources/${sid}/export?fmt=md">Markdown</a><button class="btn" data-a="mclose">Close</button></span></div>
 <div style="display:flex;gap:12px;margin-top:12px"><div style="width:140px;max-height:62vh;overflow:auto;flex:none">${s.pages.map(p=>`<div class="ch ${p.loc===loc?'on':''}" data-a="kpg:${sid}:${p.loc}"><span class="t">${L} ${p.loc}</span><span style="color:${p.status==='ok'?'#22c55e':p.status==='failed'?'#ef4444':'#999'}">●</span></div>`).join('')}</div>
 <div style="flex:1;min-width:0">${pg.status==='failed'?`<div style="color:#fca5a5">Extraction failed: ${esc(pg.error)}</div><button class="btn" data-a="kretry:${sid}:${loc}">Retry this page</button>`:''}${s.type==='pdf'&&loc?`<img src="/api/kb/sources/${sid}/pages/${loc}/image" style="max-width:100%;max-height:38vh;border:1px solid var(--bd);border-radius:8px;margin:8px 0;display:block">`:''}<div style="white-space:pre-wrap;max-height:38vh;overflow:auto;background:#0d0d0d;border:1px solid var(--bd);border-radius:10px;padding:10px">${esc(pg.text)||'<span class="mu">No text for this page.</span>'}</div><button class="btn" style="margin-top:8px" data-a="kcopy">Copy text</button></div></div>`)}
async function kpick(){const[cs,ss]=await Promise.all([api('/api/kb/collections'),api('/api/kb/sources')]);
 modal(`<b>Add from Knowledge</b><input type="search" id="kps" class="in" style="width:100%;margin:10px 0" placeholder="Search collections and documents"><div id="kpl" style="max-height:50vh;overflow:auto">${cs.map(c=>`<label class="kr" data-n="${esc(c.name.toLowerCase())}" style="display:block;padding:4px"><input type="checkbox" data-t="coll" data-id="${c.id}" data-nm="${esc(c.name)}"> 📁 <b>${esc(c.name)}</b> <span class="mu">${c.ready} ready</span></label>`+ss.filter(s=>s.coll_id===c.id).map(s=>`<label class="kr" data-n="${esc(s.title.toLowerCase())}" style="display:block;padding:4px 4px 4px 28px"><input type="checkbox" data-t="src" data-id="${s.id}" data-nm="${esc(s.title)}" ${['ready','partial'].includes(s.status)?'':'disabled'}> 📄 ${esc(s.title)} ${badge(s.status)}</label>`).join('')).join('')||'<div class="mu">No collections yet. Create one in Knowledge first.</div>'}</div><div style="margin-top:10px;display:flex;gap:8px;justify-content:flex-end"><button class="btn" data-a="mclose">Cancel</button><button class="btn on" data-a="kpdone">Use selected</button></div>`);
 $('#kps').oninput=e=>document.querySelectorAll('.kr').forEach(r=>r.style.display=r.dataset.n.includes(e.target.value.toLowerCase())?'block':'none')}
async function kact(k,v,w,el,e){
 if(k==='attach'){const r=el.getBoundingClientRect(),a=$('#amenu');a.innerHTML=[['amfiles','file','Add photos & files','PDFs, images, notebooks, text and code',1],['amkb','book','Add from Knowledge','Search your collections and documents',1],['x1','code','GitHub repository','Not built yet — planned for Phase 4',0],['x2','globe','Web search','Needs a search provider — Phase 5',0],['x3','globe','Web scraping','Not built yet — Phase 5',0],['nav:kb','library','Knowledge','Manage collections and documents',1]].map(([ac,i,t,d,on])=>`<button class="ai ${on?'':'dis'}" ${on?`data-a="${ac}"`:'disabled'}>${ic(i)}<span><b>${t}</b><br><span class="mu">${d}</span></span></button>`).join('');a.style.display='block';a.style.left=Math.max(8,Math.min(r.left,innerWidth-340))+'px';a.style.bottom=(innerHeight-r.top+8)+'px';return true}
 if(k==='amfiles'){$('#file').click();return true}
 if(k==='amkb'){await kpick();return true}
 if(k==='mclose'){closeModal();return true}
 if(k==='kpdone'){document.querySelectorAll('#kpl input:checked').forEach(i=>{if(!S.kb.find(x=>x.id===i.dataset.id))S.kb.push({t:i.dataset.t,id:i.dataset.id,name:i.dataset.nm})});closeModal();chips();return true}
 if(k==='krmc'){S.kb.splice(+v,1);chips();return true}
 if(k==='newcoll'){const n=prompt('Collection name');if(n){await api('/api/kb/collections','POST',{name:n});kbView()}return true}
 if(k==='kopen'){collView(v);return true}
 if(k==='kup'){S.upColl=v;$('#kfile').click();return true}
 if(k==='krn'){const n=prompt('Rename collection');if(n){await api('/api/kb/collections/'+v,'PATCH',{name:n});collView(v)}return true}
 if(k==='kdel'){if(confirm('Delete this collection and its index entries? Stored files are removed only if no other collection uses them.')){await api('/api/kb/collections/'+v,'DELETE');kbView()}return true}
 if(k==='kexp'){const d=await api(`/api/kb/collections/${v}/export`),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='collection.json';a.click();return true}
 if(k==='ksdel'){if(confirm('Remove this document from the index? The stored file is deleted only if nothing else uses it.')){await api('/api/kb/sources/'+v,'DELETE');collView(S.kbc)}return true}
 if(k==='kre'){await api(`/api/kb/sources/${v}/reindex`,'POST',{ocr_model:ocrModel()});collView(S.kbc);return true}
 if(k==='vsrc'){await viewSrc(v,w);return true}
 if(k==='kpg'){await viewSrc(v,w);return true}
 if(k==='kretry'){await api(`/api/kb/sources/${v}/pages/${w}/retry`,'POST',{ocr_model:ocrModel()});closeModal();if(S.page==='kb'&&S.kbc)collView(S.kbc);return true}
 if(k==='kcopy'){navigator.clipboard.writeText(S.pgtext||'');return true}
 if(k==='kask'){let name,t=v==='c'?'coll':'src';name=t==='coll'?(await api('/api/kb/collections')).find(c=>c.id===w).name:(await api('/api/kb/sources/'+w)).title;S.kb=[{t,id:w,name}];S.cid=null;S.msgs=[];S.att=[];go('chat',1);return true}
 return false}



// Task 2: scoped FTS search and source-grounded Q&A on the existing collection screen.
const __task2BaseCollView=collView;
collView=async function(id){await __task2BaseCollView(id);if(S.kbc!==id)return;const page=document.querySelector('#main .pg');if(!page)return;
 const panel=document.createElement('div');panel.className='card';panel.style.marginTop='14px';panel.innerHTML='<h2 style="margin:0 0 8px">Search this collection</h2><div style="display:flex;gap:8px;flex-wrap:wrap"><input id="kbScopedQuery" class="in" style="flex:1;min-width:220px" placeholder="Search document passages"><button id="kbScopedSearch" class="btn on">Search</button></div><div id="kbScopedResults" style="margin-top:10px"></div><hr style="border-color:var(--bd);margin:18px 0"><h2 style="margin:0 0 8px">Ask this collection</h2><div style="display:flex;gap:8px;flex-wrap:wrap"><input id="kbAskQuestion" class="in" style="flex:1;min-width:220px" placeholder="Ask a question grounded in these documents"><button id="kbAskButton" class="btn on">Ask local model</button></div><div id="kbAskStatus" class="mu" style="margin-top:8px"></div><div id="kbAskAnswer" style="white-space:pre-wrap;margin-top:8px"></div><div id="kbAskPassages" style="margin-top:8px"></div>';page.appendChild(panel);
 const search=async()=>{const q=document.querySelector('#kbScopedQuery').value.trim(),box=document.querySelector('#kbScopedResults');if(!q)return;box.textContent='Searching…';try{const rows=await api('/api/kb/search?q='+encodeURIComponent(q)+'&coll='+encodeURIComponent(id));if(!rows.length){box.textContent='No matching passages found.';return}box.innerHTML='';for(const h of rows){const card=document.createElement('div');card.className='card';card.style.margin='8px 0';const title=document.createElement('b');title.textContent=h.title+' · '+(h.reference||h.label+' '+h.loc);const text=document.createElement('div');text.className='mu';text.style.whiteSpace='pre-wrap';text.textContent=h.text;const open=document.createElement('button');open.className='btn';open.textContent='Open source passage';open.onclick=()=>viewSrc(h.sid,h.loc);card.append(title,text,open);box.appendChild(card)}}catch(err){box.textContent='Search failed: '+err.message}};
 document.querySelector('#kbScopedSearch').onclick=search;document.querySelector('#kbScopedQuery').onkeydown=e=>{if(e.key==='Enter')search()};
 const ask=async()=>{const q=document.querySelector('#kbAskQuestion').value.trim();if(!q)return;const status=document.querySelector('#kbAskStatus'),answer=document.querySelector('#kbAskAnswer'),box=document.querySelector('#kbAskPassages');status.textContent='Retrieving passages and asking the selected local Ollama model…';answer.textContent='';box.textContent='';try{const d=await api('/api/kb/collections/'+encodeURIComponent(id)+'/ask','POST',{question:q});answer.textContent=d.answer||'';status.textContent=d.status==='insufficient_evidence'?'No supporting evidence found.':'Grounded answer · '+(d.model||'local Ollama');for(const passage of d.passages||[]){const card=document.createElement('div');card.className='card';card.style.margin='8px 0';const title=document.createElement('b');const cite=(d.citations||[]).find(c=>c.sid===passage.sid&&c.loc===passage.loc);title.textContent='['+(cite?cite.id:'Source')+'] '+passage.title+' · '+(passage.reference||passage.label+' '+passage.loc);const text=document.createElement('div');text.className='mu';text.style.whiteSpace='pre-wrap';text.textContent=passage.text;const open=document.createElement('button');open.className='btn';open.textContent='Inspect source';open.onclick=()=>viewSrc(passage.sid,passage.loc);card.append(title,text,open);box.appendChild(card)}}catch(err){status.textContent='Question failed: '+err.message}};
 document.querySelector('#kbAskButton').onclick=ask;document.querySelector('#kbAskQuestion').onkeydown=e=>{if(e.key==='Enter')ask()};
};
